effect.shader:
// ------------------------------------------------------------------ a ponte para a tela do Nova

// O `(vec4(uv, 0, 1) * acLayerToScreen).xy` do AM: a coordenada da camada (Y para cima) levada ao buffer (o Y volta
// para baixo) e, na tela, pela `acCamadaParaTela` (sem a divisão da perspectiva quando ela é afim, como a matriz do
// AM); no filho de grupo, a própria UV do buffer.
vec2 camadaParaTelaDoAm(vec2 uv) {
    vec2 conteudo = max(acTamanhoDaCamada, vec2(1e-6));
    vec2 b = 0.5 + (vec2(uv.x, 1.0 - uv.y) - 0.5) * conteudo / acTamanhoDaTela;
    if (acParaTela != mat3(1.0)) return b;
    vec3 c = acCamadaParaTela * vec3(b, 1.0);
    bool afim = acCamadaParaTela[0].z == 0.0 && acCamadaParaTela[1].z == 0.0 && acCamadaParaTela[2].z == 1.0;
    return afim ? c.xy : c.xy / c.z;
}

// O `acLayerNorm` do AM: o pixel na tela levado à coordenada da camada (o retângulo do conteúdo de 0 a 1), com o Y
// para CIMA.
vec2 camadaDoPixelAm() {
    vec3 c = inverse(acCamadaParaTela) * vec3(acTela(acScreenNorm), 1.0);
    vec2 conteudo = max(acTamanhoDaCamada, vec2(1e-6));
    vec2 st = 0.5 + (c.xy / c.z - 0.5) * acTamanhoDaTela / conteudo;
    return vec2(st.x, 1.0 - st.y);
}

// ------------------------------------------------------------------ o script do AM (`animate`)

// Cada passe só roda quando o movimento dele passa de 0,0001 (e a chave dele está ligada).
bool giroLigado() { return useAngle && abs(acGiroPorQuadroDoAm) > 0.0001; }
bool escalaLigada() { return useScale && abs(acEscalaPorQuadroDoAm) > 0.0001; }
bool posicaoLigada() { return usePos && (abs(acVelocidadeDoAm.x) > 0.0001 || abs(acVelocidadeDoAm.y) > 0.0001); }

// Um buffer do mesmo tamanho, pixel por pixel (no meio do texel o filtro linear devolve o próprio texel).
vec4 copia(sampler2D img) { return texture(img, acScreenNorm); }

// ------------------------------------------------------------------ os três grupos do AM, na ordem dele

// Grupo 0: o GIRO.
vec4 passeDoGiro(sampler2D img) {
    float angle = abs(acGiroPorQuadroDoAm*tune);
    float cx = 0.5 + acPivoDoAm.x/acTamanhoDaCamada.x;
    float cy = 0.5 - acPivoDoAm.y/acTamanhoDaCamada.y;
    vec2 image_size = vec2(textureSize(img, 0));
    vec2 texelSize = 1.0 / image_size;
    vec2 center = camadaParaTelaDoAm(vec2(cx,cy));
    vec2 v = acScreenNorm.st - center;
    v.y *= image_size.y / image_size.x;
    float r = length(v);
    float d = 6.283185*r;
    float l = d*angle/360.0;
    float a = angle * 0.0174533;
    float amin = a/2.0;
    float speed = l/texelSize.x;
    int nSamples = int(clamp(speed, 1.01, 100.01));
    vec4 outColor = texture(img,acScreenNorm.st);
    for(int i=1; i<nSamples; i++ ) {
        float sampleAngle = -amin + a * float(i)/float(nSamples);
        float s = sin(sampleAngle);
        float c = cos(sampleAngle);
        mat2 rot = mat2(c, -s, s, c);
        vec2 temp = v*rot;
        temp.y = temp.y * image_size.x / image_size.y;
        outColor += texture(img, center + temp);
    }
    return outColor/float(nSamples);
}

// Grupo 1: a ESCALA.
vec4 passeDaEscala(sampler2D img) {
    vec2 image_size = vec2(textureSize(img, 0));
    vec2 texelSize = 1.0 / image_size;
    float cx = 0.5 + acPivoDoAm.x/acTamanhoDaCamada.x;
    float cy = 0.5 - acPivoDoAm.y/acTamanhoDaCamada.y;
    vec2 center = vec2(cx,cy);
    float strength = acEscalaPorQuadroDoAm*tune/length(acTamanhoDaCamada);
    vec2 v = acScreenNorm.st - camadaParaTelaDoAm(center);
    v.y *= image_size.y / image_size.x;
    float speed = length(strength / 2.0 / length(texelSize));
    speed *= length( camadaDoPixelAm() - center ); // Adaptive
    int nSamples = int(clamp(speed, 1.01, 100.01));
    vec4 outColor = texture(img,acScreenNorm.st);
    vec2 vnorm = normalize(v)*length(texelSize)*speed;
    for(int i=1; i<nSamples; i++ ) {
        vec2 offset = vnorm * (float(i) / float(nSamples - 1) - 0.5);
        offset.y = offset.y * image_size.x / image_size.y;
        outColor += texture(img, acScreenNorm.st-offset);
    }
    return outColor/float(nSamples);
}

// Grupo 2: a POSIÇÃO.
vec4 passeDaPosicao(sampler2D img) {
    vec2 texelSize = 1.0 / vec2(textureSize(img, 0));
    vec2 velocity = acVelocidadeDoAm*tune / acTamanhoDaTela;
    float speed = length(velocity / texelSize);
    int nSamples = int(clamp(speed, 1.01, 100.01));
    vec4 outColor = texture(img,acScreenNorm.st);
    for(int i=1; i<nSamples; i++ ) {
        vec2 offset = velocity * (float(i) / float(nSamples - 1) - 0.5);
        outColor += texture(img, acScreenNorm.st-offset);
    }
    return outColor/float(nSamples);
}

void main() {
    if (acPass == 0) {
        // A camada pré-multiplicada, como a textura do AM.
        vec4 c = copia(inputImg);
        fragColor = vec4(c.rgb * c.a, c.a);
        return;
    }
    if (acPass == 1) {
        fragColor = giroLigado() ? passeDoGiro(pre) : copia(pre);
        return;
    }
    if (acPass == 2) {
        fragColor = escalaLigada() ? passeDaEscala(giro) : copia(giro);
        return;
    }
    // Sem nenhum passe ligado o AM tira o efeito da lista: a camada passa como está.
    if (!giroLigado() && !escalaLigada() && !posicaoLigada()) {
        fragColor = copia(inputImg);
        return;
    }
    vec4 p = posicaoLigada() ? passeDaPosicao(escala) : copia(escala);
    fragColor = p.a > 0.0 ? vec4(min(p.rgb / p.a, vec3(1.0)), p.a) : vec4(0.0);
}
